const $=id=>document.getElementById(id);const esc=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const mode=location.pathname.startsWith('/resources')?'resource':'notice';let currentUser=null,items=[],activeItem=null,popupFile=null,popupUrl='',pendingFiles=[],busy=false;
const categoryLabels={guide:'안전 가이드',form:'서식·양식',education:'교육자료',law:'법령·기준',other:'기타'};
function api(path,options={}){return window.EHSApi.request(path,options)}function formatBytes(value){const n=Number(value||0);if(n<1024)return`${n} B`;if(n<1048576)return`${Math.round(n/1024)} KB`;return`${Math.round(n/1048576*10)/10} MB`}function utcDate(value){const text=String(value||'').trim();if(!text)return null;const normalized=/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(text)?text.replace(' ','T')+'Z':text;const date=new Date(normalized);return Number.isNaN(date.getTime())?null:date}function formatDate(value){const date=utcDate(value);return date?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(date):''}function kstInputValue(value){const date=utcDate(value);if(!date)return'';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);const map=Object.fromEntries(parts.map(part=>[part.type,part.value]));return`${map.year}-${map.month}-${map.day}T${map.hour}:${map.minute}`}function ext(name){return String(name||'').split('.').pop().toUpperCase()}function showToast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('toast').classList.add('hidden'),2400)}
function openModal(title,meta=''){$('modalTitle').textContent=title;$('modalMeta').textContent=meta;$('mainModal').classList.remove('hidden')}function closeModal(){if(busy)return;$('mainModal').classList.add('hidden');clearPending();activeItem=null}function clearPending(){if(popupUrl)URL.revokeObjectURL(popupUrl);popupFile=null;popupUrl='';pendingFiles=[]}$('modalClose').onclick=closeModal;$('mainModal').onclick=event=>{if(event.target===$('mainModal'))closeModal()};$('logoutBtn').onclick=()=>window.EHSAuth.logout();
function rowHtml(item){if(mode==='notice'){const image=item.popup_image_id?`<img src="/api/content/public/notices/${encodeURIComponent(item.id)}/popup-image" alt="" loading="lazy">`:'NOTICE';return`<article class="row notice-row" data-id="${esc(item.id)}"><div class="thumb">${image}</div><div class="row-title"><strong>${item.is_important?'<span class="tag important">중요</span>':''}${esc(item.title)}</strong>${item.content?`<p>${esc(item.content)}</p>`:''}</div><span class="file-count">첨부 ${Number(item.file_count||0)}개</span></article>`}return`<article class="row" data-id="${esc(item.id)}"><div class="thumb">${esc(ext(item.title).slice(0,5)||'EHS')}</div><div class="row-title"><strong>${item.is_pinned?'<span class="tag pinned">고정</span>':''}${!item.is_active?'<span class="tag inactive">중지</span>':''}${esc(item.title)}</strong><p>${esc(item.description||categoryLabels[item.category]||'안전자료')}</p></div><span class="meta">${esc(categoryLabels[item.category]||'기타')} · ${esc(formatDate(item.created_at))}</span><span class="file-count">파일 ${Number(item.file_count||0)}개</span></article>`}
async function loadItems(){const q=$('searchInput').value.trim(),category=mode==='resource'?$('categoryFilter').value:'';const path=mode==='notice'?`/api/content/notices?q=${encodeURIComponent(q)}${currentUser.role==='admin'?'&include_inactive=1':''}`:`/api/content/resources?q=${encodeURIComponent(q)}&category=${encodeURIComponent(category)}${currentUser.role==='admin'?'&include_inactive=1':''}`;$('contentList').innerHTML='<div class="loading">불러오는 중...</div>';try{const data=await api(path);items=mode==='notice'?data.notices||[]:data.resources||[];$('contentList').innerHTML=items.length?items.map(rowHtml).join(''):'<div class="empty">등록된 내용이 없습니다.</div>';$('contentList').querySelectorAll('[data-id]').forEach(row=>row.onclick=()=>openDetail(row.dataset.id))}catch(error){$('contentList').innerHTML=`<div class="error">${esc(error.message)}</div>`}}
$('searchBtn').onclick=loadItems;$('searchInput').onkeydown=event=>{if(event.key==='Enter')loadItems()};$('categoryFilter').onchange=loadItems;
function fileCards(files,editable=false){const attachments=(files||[]).filter(file=>file.file_role!=='popup_image');if(!attachments.length)return'<div class="empty" style="padding:20px">등록된 첨부파일이 없습니다.</div>';return`<div class="file-list">${attachments.map(file=>`<div class="file-card"><span class="file-icon">${esc(ext(file.file_name))}</span><span class="file-copy"><strong>${esc(file.file_name)}</strong><span>${esc(formatBytes(file.file_size))}</span></span><span class="file-actions"><button class="mini" type="button" data-preview="${esc(file.id)}">미리보기</button><button class="mini" type="button" data-download="${esc(file.id)}" data-name="${esc(file.file_name)}">다운로드</button>${editable?`<button class="mini delete" type="button" data-delete-file="${esc(file.id)}">삭제</button>`:''}</span></div>`).join('')}</div>`}
function bindFileActions(container,files){container.querySelectorAll('[data-preview]').forEach(button=>button.onclick=()=>window.AttachmentPreview.open((files||[]).find(file=>file.id===button.dataset.preview)));container.querySelectorAll('[data-download]').forEach(button=>button.onclick=()=>window.EHSApi.download(`/api/content/files/${encodeURIComponent(button.dataset.download)}`,button.dataset.name));container.querySelectorAll('[data-delete-file]').forEach(button=>button.onclick=()=>deleteFile(button.dataset.deleteFile))}
async function openDetail(id){openModal('내용 확인','불러오는 중...');$('modalBody').innerHTML='<div class="loading">불러오는 중...</div>';try{const data=await api(mode==='notice'?`/api/content/notices/${encodeURIComponent(id)}`:`/api/content/resources/${encodeURIComponent(id)}`);activeItem=mode==='notice'?data.notice:data.resource;renderDetail()}catch(error){$('modalBody').innerHTML=`<div class="error">${esc(error.message)}</div>`}}
function renderDetail(){const item=activeItem,files=item.files||[],popup=files.find(file=>file.file_role==='popup_image');$('modalTitle').textContent=mode==='notice'?'공지사항':'안전자료';$('modalMeta').textContent=mode==='notice'?'':formatDate(item.created_at);const badges=mode==='notice'?(item.is_important?'<span class="tag important">중요공지</span>':'<span class="tag">일반공지</span>'):(item.is_pinned?'<span class="tag pinned">고정자료</span>':`<span class="tag">${esc(categoryLabels[item.category]||'기타')}</span>`);const popupHtml=mode==='notice'&&popup?`<button class="detail-popup" type="button" data-preview="${esc(popup.id)}"><img src="/api/content/public/notices/${encodeURIComponent(item.id)}/popup-image" alt="${esc(item.title)} 팝업 이미지"></button>`:'';const bodyText=mode==='notice'?item.content:item.description||'';$('modalBody').innerHTML=`<div class="detail-head"><div>${badges}<h2>${esc(item.title)}</h2></div>${mode==='notice'?'':`<span class="detail-date">${esc(formatDate(item.updated_at||item.created_at))}</span>`}</div>${bodyText?`<div class="detail-content">${esc(bodyText)}</div>`:''}${popupHtml}<h3 class="section-title">첨부파일</h3>${fileCards(files,currentUser.role==='admin')}${currentUser.role==='admin'?`<div class="admin-detail-actions"><button class="btn" id="editBtn" type="button">수정</button><button class="btn danger" id="deleteItemBtn" type="button">삭제</button></div>`:''}`;bindFileActions($('modalBody'),files);if(currentUser.role==='admin'){$('editBtn').onclick=()=>openComposer(item);$('deleteItemBtn').onclick=deleteItem}}
async function deleteFile(fileId){if(!confirm('이 첨부파일을 삭제할까요?'))return;try{await api(`/api/admin/content/files/${encodeURIComponent(fileId)}`,{method:'DELETE'});showToast('첨부파일을 삭제했습니다.');await openDetail(activeItem.id);await loadItems()}catch(error){alert(error.message)}}async function deleteItem(){const label=mode==='notice'?'공지사항':'안전자료';if(!confirm(`${label}과 첨부파일을 모두 삭제할까요? 삭제 후 복구할 수 없습니다.`))return;try{await api(mode==='notice'?`/api/admin/content/notices/${encodeURIComponent(activeItem.id)}`:`/api/admin/content/resources/${encodeURIComponent(activeItem.id)}`,{method:'DELETE'});closeModal();showToast(`${label}를 삭제했습니다.`);await loadItems()}catch(error){alert(error.message)}}
function pendingHtml(){return pendingFiles.map((file,index)=>`<span class="pending-file">${esc(file.name)} · ${esc(formatBytes(file.size))}<button type="button" data-remove-pending="${index}">×</button></span>`).join('')}function updatePending(){$('pendingFiles').innerHTML=pendingHtml();$('pendingFiles').querySelectorAll('[data-remove-pending]').forEach(button=>button.onclick=()=>{pendingFiles.splice(Number(button.dataset.removePending),1);updatePending()})}
function setPopupFile(file){if(!file)return;if(!/^image\/(jpeg|png|webp)$/i.test(file.type)){showToast('JPG, PNG, WebP 이미지만 팝업으로 사용할 수 있습니다.');return}if(file.size>25*1024*1024){showToast('이미지는 25MB 이하만 등록할 수 있습니다.');return}if(popupUrl)URL.revokeObjectURL(popupUrl);popupFile=file;popupUrl=URL.createObjectURL(file);$('popupPreview').innerHTML=`<img src="${popupUrl}" alt="팝업 이미지 미리보기">`;$('popupClear')?.classList.remove('hidden');showToast('클립보드 이미지를 팝업으로 준비했습니다.')}
async function pasteFromClipboard(){try{const entries=await navigator.clipboard.read();for(const entry of entries){const type=entry.types.find(value=>value.startsWith('image/'));if(type){const blob=await entry.getType(type);setPopupFile(new File([blob],`popup-${Date.now()}.${type.split('/')[1].replace('jpeg','jpg')}`,{type}));return}}showToast('클립보드에 이미지가 없습니다.')}catch{showToast('Ctrl+V로 이미지를 붙여넣어 주세요.')}}
function openComposer(item=null){clearPending();activeItem=item;openModal(item?'내용 수정':mode==='notice'?'공지 등록':'안전자료 등록',item?'등록된 첨부파일은 상세 화면에서 관리할 수 있습니다.':'');if(mode==='notice')renderNoticeComposer(item);else renderResourceComposer(item)}
function renderNoticeComposer(item){$('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>제목 <span class="required">필수</span></label><input id="editTitle" maxlength="160" value="${esc(item?.title||'')}"></div><div class="field full"><label>내용</label><textarea id="editContent" maxlength="12000" placeholder="내용 없이 제목만으로도 등록할 수 있습니다.">${esc(item?.content||'')}</textarea></div><div class="field"><label>게시 시작 (한국시간)</label><input id="startAt" type="datetime-local"></div><div class="field"><label>게시 종료 (한국시간)</label><input id="endAt" type="datetime-local"></div><div class="checks"><label><input id="important" type="checkbox" ${item?.is_important?'checked':''}> 중요공지</label><label><input id="showLogin" type="checkbox" ${item?.show_on_login?'checked':''}> 로그인 화면 팝업</label><label><input id="showAfter" type="checkbox" ${item?item.show_after_login?'checked':'':'checked'}> 로그인 후 팝업</label><label><input id="active" type="checkbox" ${item?item.is_active?'checked':'':'checked'}> 게시</label></div><div class="upload-box" id="popupDrop"><div class="upload-title"><strong>팝업 이미지</strong><span>이미지를 붙여넣으면 원본 비율로 바로 미리봅니다.</span></div><div class="upload-actions"><button class="btn" id="clipboardBtn" type="button">클립보드에서 붙여넣기</button><label class="btn file-label">이미지 선택<input id="popupInput" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="btn hidden" id="popupClear" type="button">이미지 제거</button></div><div class="popup-preview" id="popupPreview"><div class="popup-empty">이 영역에서 Ctrl+V로 캡처 이미지를 붙여넣을 수 있습니다.<br>JPG · PNG · WebP</div></div></div><div class="upload-box"><div class="upload-title"><strong>공지 첨부파일</strong><span>파일당 25MB · 최대 10개</span></div><div class="upload-actions"><label class="btn file-label">파일 선택<input id="attachmentInput" type="file" multiple accept=".pdf,.hwp,.hwpx,.xls,.xlsx,.doc,.docx,.ppt,.pptx,.jpg,.jpeg,.png,.webp"></label></div><div class="pending-files" id="pendingFiles"></div></div></div><div class="modal-actions"><span class="busy" id="saveState"></span><button class="btn" id="cancelBtn" type="button">취소</button><button class="btn primary" id="saveBtn" type="button">${item?'수정 저장':'공지 등록'}</button></div>`;if(item){$('startAt').value=kstInputValue(item.start_at);$('endAt').value=kstInputValue(item.end_at)}$('clipboardBtn').onclick=pasteFromClipboard;$('popupInput').onchange=event=>setPopupFile(event.target.files[0]);$('popupClear').onclick=()=>{setPopupFile(null);if(popupUrl)URL.revokeObjectURL(popupUrl);popupFile=null;popupUrl='';$('popupPreview').innerHTML='<div class="popup-empty">팝업 이미지를 제거했습니다.</div>'};$('attachmentInput').onchange=event=>{pendingFiles.push(...event.target.files);updatePending();event.target.value=''};$('popupDrop').addEventListener('paste',handlePaste);$('cancelBtn').onclick=closeModal;$('saveBtn').onclick=saveNotice}
function renderResourceComposer(item){$('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>분류</label><select id="editCategory">${Object.entries(categoryLabels).map(([value,label])=>`<option value="${value}" ${item?.category===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>자료 제목 <span class="required">필수</span></label><input id="editTitle" maxlength="180" value="${esc(item?.title||'')}"></div><div class="field full"><label>자료 설명</label><textarea id="editDescription" maxlength="8000">${esc(item?.description||'')}</textarea></div><div class="checks"><label><input id="pinned" type="checkbox" ${item?.is_pinned?'checked':''}> 상단 고정</label><label><input id="active" type="checkbox" ${item?item.is_active?'checked':'':'checked'}> 게시</label></div><div class="upload-box"><div class="upload-title"><strong>안전자료 첨부파일</strong><span>PDF·한글·Excel·Word·PowerPoint·이미지 · 파일당 25MB</span></div><div class="upload-actions"><label class="btn file-label">파일 선택<input id="attachmentInput" type="file" multiple accept=".pdf,.hwp,.hwpx,.xls,.xlsx,.doc,.docx,.ppt,.pptx,.jpg,.jpeg,.png,.webp"></label></div><div class="pending-files" id="pendingFiles"></div></div></div><div class="modal-actions"><span class="busy" id="saveState"></span><button class="btn" id="cancelBtn" type="button">취소</button><button class="btn primary" id="saveBtn" type="button">${item?'수정 저장':'자료 등록'}</button></div>`;$('attachmentInput').onchange=event=>{pendingFiles.push(...event.target.files);updatePending();event.target.value=''};$('cancelBtn').onclick=closeModal;$('saveBtn').onclick=saveResource}
function handlePaste(event){const file=[...(event.clipboardData?.files||[])].find(value=>value.type.startsWith('image/'));if(file){event.preventDefault();event.stopPropagation();setPopupFile(file)}}document.addEventListener('paste',event=>{if(!$('mainModal').classList.contains('hidden')&&mode==='notice')handlePaste(event)});
function setBusy(value,text=''){busy=value;$('saveState').textContent=text;$('saveBtn').disabled=value;$('cancelBtn').disabled=value}
async function uploadQueued(ownerType,id){if(popupFile){setBusy(true,'팝업 이미지 등록 중...');const form=new FormData();form.append('role','popup_image');form.append('file',popupFile);await api(`/api/admin/content/notices/${encodeURIComponent(id)}/files`,{method:'POST',body:form});if(popupUrl)URL.revokeObjectURL(popupUrl);popupFile=null;popupUrl=''}let uploaded=0;while(pendingFiles.length){setBusy(true,`첨부파일 등록 중 ${uploaded+1}/${uploaded+pendingFiles.length}`);const form=new FormData();form.append('role','attachment');form.append('file',pendingFiles[0]);await api(`/api/admin/content/${ownerType==='notice'?'notices':'resources'}/${encodeURIComponent(id)}/files`,{method:'POST',body:form});pendingFiles.shift();uploaded++}}
async function saveNotice(){const title=$('editTitle').value.trim(),content=$('editContent').value.trim();if(!title){showToast('제목을 입력하세요.');return}setBusy(true,'공지 저장 중...');try{const body={title,content,is_important:$('important').checked,show_on_login:$('showLogin').checked,show_after_login:$('showAfter').checked,is_active:$('active').checked,start_at:$('startAt').value||null,end_at:$('endAt').value||null};const data=await api(activeItem?`/api/admin/content/notices/${encodeURIComponent(activeItem.id)}`:'/api/admin/content/notices',{method:activeItem?'PATCH':'POST',body:JSON.stringify(body)});await uploadQueued('notice',data.notice.id);setBusy(false);closeModal();showToast('공지사항을 저장했습니다.');await loadItems()}catch(error){setBusy(false);alert(error.message)}}
async function saveResource(){const title=$('editTitle').value.trim();if(!title){showToast('자료 제목을 입력하세요.');return}setBusy(true,'자료 저장 중...');try{const body={category:$('editCategory').value,title,description:$('editDescription').value.trim(),is_pinned:$('pinned').checked,is_active:$('active').checked};const data=await api(activeItem?`/api/admin/content/resources/${encodeURIComponent(activeItem.id)}`:'/api/admin/content/resources',{method:activeItem?'PATCH':'POST',body:JSON.stringify(body)});await uploadQueued('resource',data.resource.id);setBusy(false);closeModal();showToast('안전자료를 저장했습니다.');await loadItems()}catch(error){setBusy(false);alert(error.message)}}
window.AttachmentPreview.init({getPreviewTicket:file=>api(`/api/content/files/${encodeURIComponent(file.id)}/preview-ticket`,{method:'POST'}),download:file=>window.EHSApi.download(`/api/content/files/${encodeURIComponent(file.id)}`,file.file_name),onError:error=>showToast(error.message),maxPreviewBytes:25*1024*1024});
(async()=>{try{currentUser=await window.EHSAuth.requireUser();window.__EHS_PAGE_USER=currentUser;document.dispatchEvent(new CustomEvent('ehs:user-ready',{detail:currentUser}));const admin=currentUser.role==='admin';$('userLabel').textContent=[currentUser.company_name,currentUser.position,currentUser.name].filter(Boolean).join(' · ')||currentUser.email||'';$('pageTitle').textContent=mode==='notice'?'공지사항':'안전자료실';$('pageMeta').textContent=mode==='notice'?'EHS 주요 안내와 첨부자료를 확인합니다.':'안전보건 양식·교육자료·법령을 미리 보고 내려받습니다.';$('listTitle').textContent=mode==='notice'?'전체 공지':'안전자료 목록';$('categoryFilter').classList.toggle('hidden',mode!=='resource');$('newBtn').classList.toggle('hidden',!admin);$('newBtn').textContent=mode==='notice'?'공지 등록':'안전자료 등록';$('newBtn').onclick=()=>openComposer();await loadItems()}catch(error){if(error?.status===401)return;$('contentList').innerHTML=`<div class="error">${esc(error.message)}</div>`}})();
